import{at as e,n as t,rt as n,xt as r}from"./chunks/framework.DIOWbp6D.js";var i=JSON.parse(`{"title":"Engines","description":"","frontmatter":{},"headers":[],"relativePath":"ecosystem/engines.md","filePath":"ecosystem/engines.md"}`),a={name:`ecosystem/engines.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h1 id="engines" tabindex="-1">Engines <a class="header-anchor" href="#engines" aria-label="Permalink to “Engines”">​</a></h1><p>Engines are the pluggable implementations of Handl&#39;s language operations. A language definition is <em>data</em> — syntax, grammar, AST shapes, eval schemes, and type rules live in <code>Language</code> records, not in engine code. An engine interprets that data, so swapping one changes how a language runs, not what it means.</p><p>Every operation follows the same shape: a small <strong>abstraction</strong> crate owns the contract (marker type, request, trait, shared helpers) and one or more <strong>engine</strong> crates implement it. The kit decides which engine fills each slot.</p><h2 id="the-operations" tabindex="-1">The operations <a class="header-anchor" href="#the-operations" aria-label="Permalink to “The operations”">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Contract</th><th>Engines</th></tr></thead><tbody><tr><td>lex</td><td><code>tool-lex</code></td><td><code>tool-lex-pattern</code> — data-driven rules</td></tr><tr><td>parse</td><td><code>tool-parse</code></td><td><code>tool-parse-pratt</code> — Pratt, grammar rows</td></tr><tr><td>transform</td><td><code>tool-transform</code></td><td><code>tool-transform-rewrite</code> — rule-interpreting</td></tr><tr><td>typecheck</td><td><code>tool-typecheck</code></td><td><code>tool-typecheck-nbe</code> — normalization by evaluation</td></tr><tr><td>eval</td><td><code>exec</code></td><td><code>exec-tree-walk</code> (reference), <code>exec-bytecode</code> (stack VM), <code>exec-cranelift</code> (JIT/object)</td></tr></tbody></table><p>Two further families sit alongside: <code>tool-compile-*</code> lowers <code>Term</code>s to concrete targets (see <a href="#compiler-backends">Compiler backends</a>), and the <code>ext-*</code> crates package the same operations as dynamic <code>hnl</code> extensions (see <a href="/docs/ecosystem/extensions.html">Extensions</a>).</p><h2 id="shared-substrate" tabindex="-1">Shared substrate <a class="header-anchor" href="#shared-substrate" aria-label="Permalink to “Shared substrate”">​</a></h2><ul><li><a href="https://github.com/handl-lang/engine" target="_blank" rel="noreferrer">engine</a> — <code>Term</code>, <code>Model</code>, and the arena view every engine uses.</li><li><a href="https://github.com/handl-lang/engine-eqsat" target="_blank" rel="noreferrer">engine-eqsat</a> — the e-graph <strong>search</strong> interpretation over kernel <code>Term</code>s: saturation and extraction via <code>handl-egraph</code>, with laws, guards, and cost specs as kit data.</li></ul><h2 id="tooling-instruments" tabindex="-1">Tooling instruments <a class="header-anchor" href="#tooling-instruments" aria-label="Permalink to “Tooling instruments”">​</a></h2><p>The <code>tool-*</code> family beyond the five core operations:</p><ul><li><a href="https://github.com/handl-lang/tool-fmt" target="_blank" rel="noreferrer">tool-fmt</a> — data-driven AST formatter; renders an <code>Ast</code> using only language data, no hardcoded kinds.</li><li><a href="https://github.com/handl-lang/tool-lint" target="_blank" rel="noreferrer">tool-lint</a> — rule-based linter over a <code>lang.lints</code> table plus named native checks.</li><li><a href="https://github.com/handl-lang/tool-test" target="_blank" rel="noreferrer">tool-test</a> — bootstrap test runner: discovery, tag/filter predicates, scheduling.</li><li><a href="https://github.com/handl-lang/tool-watch" target="_blank" rel="noreferrer">tool-watch</a> — cross-platform filesystem watcher: typed events, filters, debounce.</li><li><a href="https://github.com/handl-lang/tool-codemod" target="_blank" rel="noreferrer">tool-codemod</a> — the spec/model layer of the declarative codemod engine.</li></ul><h2 id="compiler-backends" tabindex="-1">Compiler backends <a class="header-anchor" href="#compiler-backends" aria-label="Permalink to “Compiler backends”">​</a></h2><p><code>tool-compile-*</code> emitters lower Handl <code>Term</code> arrow graphs to concrete targets. Canonical/debug targets round-trip the IR itself; the performance targets emit real code.</p><table tabindex="0"><thead><tr><th>Repo</th><th>Target</th></tr></thead><tbody><tr><td><a href="https://github.com/handl-lang/tool-compile-term" target="_blank" rel="noreferrer">tool-compile-term</a></td><td><code>Term</code> JSON — canonical form</td></tr><tr><td><a href="https://github.com/handl-lang/tool-compile-handl" target="_blank" rel="noreferrer">tool-compile-handl</a></td><td>Handl source (Hughes arrow dialect)</td></tr><tr><td><a href="https://github.com/handl-lang/tool-compile-sexp" target="_blank" rel="noreferrer">tool-compile-sexp</a></td><td>S-expressions</td></tr><tr><td><a href="https://github.com/handl-lang/tool-compile-dot" target="_blank" rel="noreferrer">tool-compile-dot</a></td><td>Graphviz DOT graphs</td></tr><tr><td><a href="https://github.com/handl-lang/tool-compile-js" target="_blank" rel="noreferrer">tool-compile-js</a></td><td>JavaScript</td></tr><tr><td><a href="https://github.com/handl-lang/tool-compile-llvm" target="_blank" rel="noreferrer">tool-compile-llvm</a></td><td>LLVM IR — the escape hatch to native code</td></tr><tr><td><a href="https://github.com/handl-lang/tool-compile-triton" target="_blank" rel="noreferrer">tool-compile-triton</a></td><td>Triton kernels (GPU)</td></tr><tr><td><a href="https://github.com/handl-lang/tool-compile-cuda" target="_blank" rel="noreferrer">tool-compile-cuda</a></td><td>CUDA C++ — templated <code>__global__</code> + <code>extern &quot;C&quot;</code> launcher</td></tr></tbody></table><p>Emitters decline uncovered ops by name rather than emitting stubs — a compile failure is explicit, never silent.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to “References”">​</a></h2><p>The design lineage is academic: equality saturation comes from the e-graph literature (egg/egglog), normalization-by-evaluation from the type-checking literature, and Pratt/precedence parsing from classical parser theory. See the <a href="/docs/ecosystem/bibliography.html">bibliography</a> for the foundations; implementation-specific references are collected under &quot;Tooling and implementation&quot; there.</p>`,17)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};